import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry sigmoid_forward(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 numel
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<16>;
    .reg .b64 %rd<12>;
    .reg .f32 %f<24>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r5, [numel];

    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r4, %r1, %r2, %r3;      // quad index

    mul.lo.u32 %r6, %r4, 4;             // base element index
    add.u32 %r7, %r6, 3;
    setp.lt.u32 %p1, %r7, %r5;          // full quad in bounds?
    @%p1 bra FULL;

TAIL_LOOP:
    setp.ge.u32 %p2, %r6, %r5;
    @%p2 bra DONE;
    mul.wide.u32 %rd3, %r6, 4;
    add.s64 %rd4, %rd1, %rd3;
    add.s64 %rd5, %rd2, %rd3;
    ld.global.f32 %f1, [%rd4];
    mul.f32 %f2, %f1, 0fBFB8AA3B;       // -x * log2(e)
    ex2.approx.f32 %f2, %f2;            // exp(-x)
    add.f32 %f2, %f2, 0f3F800000;       // 1 + exp(-x)
    div.rn.f32 %f2, 0f3F800000, %f2;    // 1 / (1 + exp(-x))
    st.global.f32 [%rd5], %f2;
    add.u32 %r6, %r6, 1;
    bra TAIL_LOOP;

FULL:
    mul.wide.u32 %rd3, %r6, 4;
    add.s64 %rd4, %rd1, %rd3;
    add.s64 %rd5, %rd2, %rd3;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];

    mul.f32 %f5, %f1, 0fBFB8AA3B;
    ex2.approx.f32 %f5, %f5;
    add.f32 %f5, %f5, 0f3F800000;
    div.rn.f32 %f1, 0f3F800000, %f5;

    mul.f32 %f6, %f2, 0fBFB8AA3B;
    ex2.approx.f32 %f6, %f6;
    add.f32 %f6, %f6, 0f3F800000;
    div.rn.f32 %f2, 0f3F800000, %f6;

    mul.f32 %f7, %f3, 0fBFB8AA3B;
    ex2.approx.f32 %f7, %f7;
    add.f32 %f7, %f7, 0f3F800000;
    div.rn.f32 %f3, 0f3F800000, %f7;

    mul.f32 %f8, %f4, 0fBFB8AA3B;
    ex2.approx.f32 %f8, %f8;
    add.f32 %f8, %f8, 0f3F800000;
    div.rn.f32 %f4, 0f3F800000, %f8;

    st.global.v4.f32 [%rd5], {%f1, %f2, %f3, %f4};

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sigmoid_forward")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()
        out = torch.empty_like(x)
        n = x.numel()
        quads = (n + 3) // 4
        block_x = 256
        grid_x = (quads + block_x - 1) // block_x
        module.launch(
            "sigmoid_forward",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

